package org.apache.commons.lang3.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_16_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Test case for a hexadecimal number with a suffix
        String input = "0x1.8p1";
        try {
            Number result = NumberUtils.createNumber(input);
            fail("NumberFormatException was expected for input: " + input);
        } catch (NumberFormatException e) {
            // Expected exception
            assertEquals("0x1.8p1 is not a valid number.", e.getMessage());
        }
    }
}

